export const subjectRoadmaps = allRoadmaps.reduce((acc, rm) => {
  if (rm.subjectId) acc[rm.subjectId] = rm;
  if (rm.code) acc[rm.code] = rm;
  if (rm.name) acc[rm.name.toLowerCase()] = rm;
  return acc;
}, {});

export function getSubjectRoadmap(idOrCodeOrName) {
  if (!idOrCodeOrName) return allRoadmaps[0] || null;
  const rawKey = String(idOrCodeOrName).trim().toLowerCase();
  const normKey = rawKey.replace(/[\s-_]/g, '');
  return (
    subjectRoadmaps[idOrCodeOrName] ||
    subjectRoadmaps[rawKey] ||
    allRoadmaps.find(
      (rm) =>
        rm.subjectId.toLowerCase() === rawKey ||
        rm.code.toLowerCase() === rawKey ||
        rm.name.toLowerCase() === rawKey ||
        rm.subjectId.toLowerCase().replace(/[\s-_]/g, '') === normKey ||
        rm.code.toLowerCase().replace(/[\s-_]/g, '') === normKey ||
        rm.name.toLowerCase().replace(/[\s-_]/g, '') === normKey
    ) ||
    allRoadmaps[0]
  );
}

export function getSemesterRoadmaps(semesterNum) {
  const sem = Number(semesterNum) || 1;
  return allRoadmaps
    .filter((rm) => rm.semester === sem)
    .sort((a, b) => a.recommendedLearningOrder - b.recommendedLearningOrder);
}
